ection or payment_difference_handling == 'open'\\">\\n                                    <div class=\\"o_wrap_field d-flex d-sm-contents flex-column mb-3 mb-sm-0\\">\\n                                        <div class=\\"o_cell o_wrap_label text-break text-900\\">\\n                                            <label for=\\"writeoff_account_id\\" string=\\"Post Difference In\\" class=\\"oe_edit_only\\"/>\\n                                        </div>\\n                                        <div class=\\"o_cell o_wrap_input text-break\\">\\n                                            <field name=\\"writeoff_account_id\\" string=\\"Post Difference In\\" options=\\"{'no_create': True}\\" required=\\"payment_difference_handling == 'reconcile' and not early_payment_discount_mode\\"/>\\n                                        </div>\\n                                    </div>\\n                                    <div class=\\"o_wrap_field d-flex d-sm-contents flex-column mb-3 mb-sm-0\\">\\n                                        <div class=\\"o_cell o_wrap_label text-break text-900\\">\\n                                            <label for=\\"writeoff_label\\" class=\\"oe_edit_only\\" string=\\"Label\\" invisible=\\"writeoff_is_exchange_account\\"/>\\n                                        </div>\\n                                        <div class=\\"o_cell o_wrap_input text-break\\">\\n                                            <field name=\\"writeoff_label\\" required=\\"payment_difference_handling == 'reconcile'\\" invisible=\\"writeoff_is_exchange_account\\"/>\\n                                        </div>\\n                                    </div>\\n                                </div>\\n                            </div>\\n                        </group>\\n                        <group name=\\"group2\\">\\n                            <label for=\\"amount\\"/>\\n                            <div name=\\"amount_div\\" class=\\"o_row\\">\\n          